//! Cross-repository convergence with card-game-template (moritzbrantner/game-server#10).
//!
//! `tests/fixtures/card-game-template/uno-replay-v1.txt` is generated by
//! card-game-template (`packages/game-fixtures/src/game-server.ts`) from its real UNO
//! server session. It records the exact external-simulation exchanges and the local
//! TypeScript replay fingerprint. This test drives the same accepted move through
//! `MatchRuntime` + `ExternalSimulationAdapter`, answering each request from the
//! transcript, and requires byte-identical requests and the same fingerprint. The UNO
//! rules stay in TypeScript; game-server keeps identity, sequencing and ticks.

use game_server::{
    CommandOutcome, ExternalSimulationAdapter, ExternalSimulationBridge, ExternalSimulationError,
    MatchRuntime, RECONNECT_TOKEN_BYTES, ReconnectToken, verify_replay,
};
use std::sync::{Arc, Mutex};

const FIXTURE: &str = include_str!("fixtures/card-game-template/uno-replay-v1.txt");

struct Exchange {
    operation: String,
    request: Vec<u8>,
    response: Vec<u8>,
}

struct Fixture {
    players: Vec<u32>,
    command_player: u32,
    command_sequence: u32,
    command_payload: Vec<u8>,
    final_tick: u64,
    fingerprint: u64,
    exchanges: Vec<Exchange>,
}

fn hex(text: &str) -> Vec<u8> {
    assert!(text.len().is_multiple_of(2), "odd hex length");
    (0..text.len())
        .step_by(2)
        .map(|index| u8::from_str_radix(&text[index..index + 2], 16).expect("hex byte"))
        .collect()
}

fn parse_fixture() -> Fixture {
    let mut players = Vec::new();
    let mut command = None;
    let mut final_tick = None;
    let mut fingerprint = None;
    let mut exchanges = Vec::new();
    for line in FIXTURE.lines() {
        let (key, value) = line.split_once('=').expect("key=value line");
        match key {
            "schema" | "protocol_version" => assert_eq!(value, "1", "{key}"),
            "player" => players.push(value.split_once(':').unwrap().0.parse().unwrap()),
            "command" => {
                let mut parts = value.splitn(3, ':');
                command = Some((
                    parts.next().unwrap().parse::<u32>().unwrap(),
                    parts.next().unwrap().parse::<u32>().unwrap(),
                    hex(parts.next().unwrap()),
                ));
            }
            "expected_final_tick" => final_tick = Some(value.parse().unwrap()),
            "expected_replay_fingerprint" => {
                fingerprint = Some(u64::from_str_radix(value, 16).unwrap());
            }
            "exchange" => {
                let mut parts = value.splitn(3, ':');
                exchanges.push(Exchange {
                    operation: parts.next().unwrap().to_owned(),
                    request: hex(parts.next().unwrap()),
                    response: hex(parts.next().unwrap()),
                });
            }
            _ => {}
        }
    }
    let (command_player, command_sequence, command_payload) = command.expect("command line");
    Fixture {
        players,
        command_player,
        command_sequence,
        command_payload,
        final_tick: final_tick.expect("expected_final_tick"),
        fingerprint: fingerprint.expect("expected_replay_fingerprint"),
        exchanges,
    }
}

/// Plays back the TypeScript endpoint: state-changing requests must arrive in the
/// recorded order with identical bytes; snapshot reads are answered once reached.
#[derive(Clone)]
struct TranscriptBridge {
    exchanges: Arc<Vec<Exchange>>,
    cursor: Arc<Mutex<usize>>,
}

impl TranscriptBridge {
    fn new(fixture: &Fixture) -> Self {
        let exchanges = fixture
            .exchanges
            .iter()
            .map(|exchange| Exchange {
                operation: exchange.operation.clone(),
                request: exchange.request.clone(),
                response: exchange.response.clone(),
            })
            .collect();
        Self {
            exchanges: Arc::new(exchanges),
            cursor: Arc::new(Mutex::new(0)),
        }
    }

    fn mutations_consumed(&self) -> bool {
        let cursor = *self.cursor.lock().unwrap();
        self.exchanges[cursor..]
            .iter()
            .all(|exchange| exchange.operation == "snapshot")
    }
}

impl ExternalSimulationBridge for TranscriptBridge {
    fn exchange(&self, request: &[u8]) -> Result<Vec<u8>, ExternalSimulationError> {
        let mut cursor = self.cursor.lock().unwrap();
        if let Some(next) = self.exchanges.get(*cursor)
            && next.request == request
        {
            *cursor += 1;
            return Ok(next.response.clone());
        }
        let reached_snapshot = self.exchanges[..*cursor]
            .iter()
            .rev()
            .find(|exchange| exchange.operation == "snapshot" && exchange.request == request);
        if let Some(snapshot) = reached_snapshot {
            return Ok(snapshot.response.clone());
        }
        Err(ExternalSimulationError::bridge(format!(
            "request diverged from card-game-template transcript at exchange {}",
            *cursor
        )))
    }
}

#[test]
fn server_hosted_uno_move_converges_on_the_local_replay_fingerprint() {
    let fixture = parse_fixture();
    let bridge = TranscriptBridge::new(&fixture);
    let observer = bridge.clone();
    let simulation = ExternalSimulationAdapter::connect(bridge).unwrap();
    let mut runtime = MatchRuntime::new_with_replay_capture(simulation, fixture.final_tick);

    let mut leases = Vec::new();
    for (index, expected_player) in fixture.players.iter().enumerate() {
        let lease = runtime
            .admit(ReconnectToken([index as u8 + 1; RECONNECT_TOKEN_BYTES]))
            .unwrap();
        assert_eq!(lease.player_id, *expected_player);
        leases.push(lease);
    }
    let lease = leases
        .iter()
        .find(|lease| lease.player_id == fixture.command_player)
        .unwrap();
    assert_eq!(
        runtime
            .submit_command(
                lease.player_id,
                lease.connection_epoch,
                fixture.command_sequence,
                &fixture.command_payload,
            )
            .unwrap(),
        CommandOutcome::Applied
    );

    let snapshot = runtime.advance_tick().unwrap();
    assert_eq!(snapshot.tick, fixture.final_tick);
    assert_eq!(snapshot.state_hash, fixture.fingerprint);
    assert!(observer.mutations_consumed());

    let replay = runtime.replay_log().unwrap().clone();
    let verification = verify_replay(
        ExternalSimulationAdapter::connect(TranscriptBridge::new(&fixture)).unwrap(),
        &replay,
    )
    .unwrap();
    assert_eq!(verification.final_snapshot.state_hash, fixture.fingerprint);
}
